mentList* fAppointments;public:	// Construction/Destruction	virtual void DoPostCreate(TDocument* itsDocument);				// OVERRIDE	// Printing	virtual void PrepareToPrint();	// Drawing#ifdef MACAPP_R_13	virtual void DrawRangeOfCells(const GridCell& startCell,								const GridCell& stopCell, const VRect& aRect);		// OVERRIDE#else	virtual void DrawRangeOfCells(GridCell startCell,								GridCell stopCell, const VRect& aRect);		// OVERRIDE#endif	virtual void GetAppointmentParams(short theRow);	virtual CStr255 GetText(const GridCell& aCell) const;			// OVERRIDE	virtual void GetText(GridCell aCell, CStr255& itsText) { itsText = GetText(aCell); }			// OVERRIDE	// Misc.	virtual bool IsActive() CONST;					// OVERRIDE};//----------------------------------------------------------------------------------------// CLASS TSchedulePrintHandler//----------------------------------------------------------------------------------------class TSchedulePrintHandler : public TStdPrintHandler{private:	TView* 				fHeader;	TView*				fFooter;	bool				fPrintHeader;	bool				fPrintFooter;public:	// Construction/Destruction	TSchedulePrintHandler(TDocument* itsDocument, TView* itsView);	virtual ~TSchedulePrintHandler();										// OVERRIDE	// Printing	virtual void AdornPage();									// OVERRIDE	virtual VPoint CalcViewPerPage();			// OVERRIDE	virtual void CalcViewPerPage(VPoint& viewPerPage) 		{ viewPerPage = CalcViewPerPage(); }		virtual void DrawPageAdornment(TView* theView);	virtual VPoint LocatePageInterior(long thePageNumber);			// OVERRIDE	virtual void LocatePageInterior(long thePageNumber, VPoint& pageInterior) 		{ pageInterior = LocatePageInterior(thePageNumber); }			virtual bool Print(CommandNumber itsCommandNumber);			// OVERRIDE	virtual void Print(CommandNumber itsCommandNumber, bool& proceed)		{ proceed = Print(itsCommandNumber); }};//----------------------------------------------------------------------------------------// Global initialization procedure//----------------------------------------------------------------------------------------extern void InitUSchedulePrinting();	// Call this routine at initialization time#endif